# Boundary workload: diagnostic marker near beginning → λ
from collections import deque

def traced(function):
    def wrapper(*args, **kwargs):
        return function(*args, **kwargs)
    return wrapper

class Strategy:
    """Representative nested state, Unicode 日本語, and multiline text."""

    def __init__(self):
        self.prices = deque(maxlen=32)

    @traced
    def on_event(self, event):
        self.prices.append(event["tick"]["price_level"])
        recent = [price for price in self.prices if price > 0]
        if len(recent) < 2:
            return []
        return [{"type": "submit_market", "side": "buy", "quantity": 1}]

